package sum

// Sum adds xs.
func Sum(xs ...int) int {
	n := 0
	for _, x := range xs {
		n += x
	}
	return n
}

// Mean averages xs.
func Mean(xs ...int) int {
	if len(xs) == 0 {
		return 0
	}
	return Sum(xs...) / len(xs)
}

